/**
 * ValueProof — Brand assets (locked Jul 2026)
 * The wordmark: serif 'ValueProof' — oversized navy V doubling as a gold
 * checkmark, navy 'alue', green 'Proof' with a gold roof + chimney over the
 * first O. The V-mark stands alone as the icon/favicon. This module is the
 * single source for logo art; webapp/marketing/report all import from here.
 */

/** Full wordmark, transparent PNG (height 240), as a data URI. */
export const WORDMARK_DATA_URI =
  'data:image/png;base64,';

/** Standalone V-mark (navy serif V + gold check) as inline SVG markup. */
export const VMARK_SVG =
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><text x="4" y="88" font-family="Georgia, 'Times New Roman', serif" font-size="100" fill="#0D1B2A">V</text><path d="M52 70 C 62 46, 76 26, 94 10 C 82 30, 70 52, 63 80 L 56 82 Z" fill="#C8A15A"/></svg>`;

/** V-mark as an SVG data URI — favicon + small placements. */
export const VMARK_DATA_URI =
  'data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%20100%20100%22%3E%3Ctext%20x%3D%224%22%20y%3D%2288%22%20font-family%3D%22Georgia%2C%20%27Times%20New%20Roman%27%2C%20serif%22%20font-size%3D%22100%22%20fill%3D%22%230D1B2A%22%3EV%3C/text%3E%3Cpath%20d%3D%22M52%2070%20C%2062%2046%2C%2076%2026%2C%2094%2010%20C%2082%2030%2C%2070%2052%2C%2063%2080%20L%2056%2082%20Z%22%20fill%3D%22%23C8A15A%22/%3E%3C/svg%3E';

/** <link> tag for page heads. */
export const FAVICON_LINK = `<link rel="icon" type="image/svg+xml" href="${VMARK_DATA_URI}">`;

/** Wordmark <img> for headers; pass a CSS height (px). */
export function wordmarkImg(height: number, extraStyle = ''): string {
  return `<img src="${WORDMARK_DATA_URI}" alt="ValueProof" style="height:${height}px;width:auto;display:block;${extraStyle}"/>`;
}
